import {icon} from './icons';
import {familyHint,deployment,modelLabel,modelKind} from './model-display';
import {batchTracks} from './workflow';
import {validateBundle,planImport} from './library';
import {exportLibrary,importLibrary,fileFingerprint,download} from './library-io';
import {Config,Track,mergeConfig,validEndpoint} from './core';
import {upgradeConfig,resolve,validateConnection,validateModel,modelList} from './profiles';
import type {Connection,ModelProfile} from './profile-types';
import {classify} from './providers';
import * as db from './db';
const $=(id:string)=>document.getElementById(id) as any;
const esc=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(text:string,action:string,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const opts=(values:any[],selected:any)=>values.map(v=>{const [id,name]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(name)}</option>`}).join('');
const field=(label:string,id:string,value:any,type='text',attrs='')=>`<div><label class="label" for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const select=(label:string,id:string,values:any[],value:any,attrs='')=>`<div><label class="label" for="${id}">${label}</label><select id="${id}" ${attrs}>${opts(values,value)}</select></div>`;
const area=(label:string,id:string,value:any,attrs='')=>`<div><label class="label" for="${id}">${label}</label><textarea id="${id}" ${attrs}>${esc(value)}</textarea></div>`;
let aiEditor:''|'connection'|'model'='',newEntity=false,aiFilter='',aiSearch='',testResults:Record<string,string>={};
let readyState:any=null,missingIds=new Set<string>(),bulk=new Set<string>(),backupInput:any=null,importReport='';
let cacheState:any={rounds:0,worlds:0,backups:[]};
let c:Config,tracks:Track[]=[],runtime:any={},page='diagnostics',selected='',scene='',search='',filter='',drawer=false,connectionId='',modelId='',section='connection';
let drafts:Record<string,Track>={},connectionDrafts:Record<string,Connection>={},modelDrafts:Record<string,ModelProfile>={},taskDraft:any,prefs:any,preview:HTMLAudioElement|null=null,previewURL='',busy=false,focusReturn:HTMLElement|null=null;const rawHeaders:Record<string,string>={},rawExtra:Record<string,string>={};
const live=()=>tracks.filter(t=>!t.deleted),track=()=>tracks.find(t=>t.id===selected&&!t.deleted),draft=()=>track()?(drafts[selected]??=structuredClone(track())):null;
const cp=()=>connectionDrafts[connectionId]??=structuredClone(c.connections.find(p=>p.id===connectionId));
const mp=()=>modelId?(modelDrafts[modelId]??=structuredClone(c.models.find(m=>m.id===modelId))):null;
const moodName=(id:string)=>c.moods.find(m=>m.id===id)?.name||'未分类';
const modelName=(id:string)=>{const m=c.models.find(m=>m.id===id);return m?modelLabel(m,c.connections.find(p=>p.id===m.connectionId)):'未配置';};
let noticeTimer:ReturnType<typeof setTimeout>|undefined;
function notice(text:string,duration=4000){if(noticeTimer!==undefined)clearTimeout(noticeTimer);noticeTimer=undefined;$('notice').textContent=text;if(text)noticeTimer=setTimeout(()=>{$('notice').textContent='';noticeTimer=undefined;},duration);}
async function send(type:string,extra:any={}){const r=await chrome.runtime.sendMessage({type,...extra});if(!r?.ok)throw Error(r?.error||'扩展后台没有响应，请重新加载扩展');return r.data;}
async function persist(patch:any){c=upgradeConfig(await send('saveConfig',{patch}));}
async function reloadTracks(){tracks=await db.all('tracks');const keys=new Set(await db.keys('blobs'));missingIds=new Set(tracks.filter(t=>!keys.has(t.id)).map(t=>t.id));if(!track())selected=live()[0]?.id||'';}
function stopPreview(){preview?.pause();preview=null;if(previewURL)URL.revokeObjectURL(previewURL);previewURL='';}
async function listen(id:string){stopPreview();const t=tracks.find(t=>t.id===id),record=await db.get('blobs',id);if(!record?.blob)throw Error('音频副本不存在，请重新导入');previewURL=URL.createObjectURL(record.blob);preview=new Audio(previewURL);preview.volume=(drafts[id]?.gain??t.gain)*c.volume;try{await preview.play();notice('正在试听：'+t.name+'；离开此页停止');}catch{stopPreview();throw Error('浏览器无法播放此音频，请转换为 MP3 或 WAV 后导入');}}
function status(){return `<div class="status ${runtime.error?'error':''}"><span class="status-icon">${icon('music')}</span><div class="text"><strong>${esc(!runtime.enabled?'自动配乐未开启':runtime.paused?'已手动暂停':runtime.status||'等待游玩页面')}</strong><p class="small">${esc(runtime.trackName||'尚未播放')} ${runtime.decision?' · '+esc(moodName(runtime.decision.mood)):''}</p><small>${esc(runtime.error||'情境由指定模型判断，音乐在本地匹配。')}</small></div></div>`;}
function list(mood=''){
 const data=tracks.filter(t=>page==='trash'?t.deleted:!t.deleted).filter(t=>!mood||t.moods.includes(mood)).filter(t=>mood||!filter||(filter==='unclassified'?!t.moods.some(id=>c.moods.some(m=>m.id===id&&!m.disabled)):filter==='missing'?missingIds.has(t.id):t.moods.includes(filter))).filter(t=>mood||!search||(t.name+t.moods.map(moodName).join()+t.tags.join()).includes(search));
 if(!data.length)return `<div class="empty"><div class="empty-icon">${icon('music')}</div><h2>${page==='trash'?'回收站为空':live().length?'这里还没有匹配的音乐':'把故事的声音放进来'}</h2><p>${page==='trash'?'移入这里的曲目可以恢复。':'导入音频，选择适用情绪。文件保存在本地，不上传给模型。'}</p>${page==='trash'?'':b(icon('plus')+'导入音乐','import','','primary')}</div>`;
 return `<div class="list-heading"><span>曲目 / 标签</span><span>${data.length} 首</span></div><div class="track-list">${data.map((t,i)=>`<div class="track-row ${t.id===selected?'selected':''}">${page==='trash'?`<span class="track-num">${i+1}</span>`:`<input type="checkbox" data-bulk="${t.id}" aria-label="选择 ${esc(t.name)}" ${bulk.has(t.id)?'checked':''}>`}${b(`${esc(t.name)}<small>${esc(t.tags.join(' · ')||'未设置标签')}</small>`,'select',`data-id="${t.id}" title="${esc(t.name)}" aria-pressed="${t.id===selected}"`,'name')}<span class="row-mood">${esc(missingIds.has(t.id)?'音频缺失':t.moods.map(moodName).join(' / ')||'待分类')}</span>${b(page==='trash'?icon('restore'):icon('play'),page==='trash'?'restore':'listen',`data-id="${t.id}" aria-label="${page==='trash'?'恢复':'试听'} ${esc(t.name)}"`,'icon')}</div>`).join('')}</div>`;
}
function checks(label:string,group:string,values:any[],chosen:string[]){return `<fieldset class="mood-field"><legend class="label">${label}</legend><div class="checks">${values.map(v=>{const [id,name]=Array.isArray(v)?v:[v,v];return `<label><input type="checkbox" data-check="${group}" value="${esc(id)}" ${chosen.includes(id)?'checked':''}>${esc(name)}</label>`}).join('')}</div></fieldset>`;}
function editor(){const t=draft();if(!t)return '<aside class="inspector"><p>选择一首音乐，查看适用场景与标签。</p></aside>';return `<aside class="inspector"><div class="row between"></div><h2 class="edit-name">${esc(t.name)}</h2><p class="small">${(t.size/1048576).toFixed(1)} MB · 修改后保存到本地</p><div class="stack">${b(icon('play')+'试听这首音乐','listen',`data-id="${t.id}"`,'outline')}${field('曲目名称','trackName',t.name,'text','data-track="name"')}${checks('适用情绪 · 可多选','moods',c.moods.map(m=>[m.id,m.name]),t.moods)}${checks('适用标签','tags',c.tags,t.tags)}<details><summary>排除情境 · ${t.exclude.length} 项</summary>${checks('排除优先于适用标签','exclude',c.tags,t.exclude)}</details>${area('适用说明','description',t.description,'data-track="description"')}${b('转换说明为标签 · 1 次请求','convert','','outline')}${select('音乐强度','intensity',[[-1,'不限强度'],[0,'平静'],[1,'轻微起伏'],[2,'明显紧张 / 激动'],[3,'激烈 / 高潮']],t.intensity,'data-track="intensity"')}${field('单曲音量','gain',t.gain,'range','min="0" max="1" step=".01" data-track="gain"')}<div class="editor-bottom"><p id="dirty" class="small">${drafts[t.id]&&JSON.stringify(t)!==JSON.stringify(track())?'有未保存的修改':'已保存到本地'}</p><div class="row">${b('保存修改','saveTrack','','primary')}${b('还原','resetTrack','','outline')}</div>${b('移入回收站','remove','','danger')}</div></div></aside>`;}
function scenes(){const m=c.moods.find(m=>m.id===scene)||c.moods[0];scene=m.id;return `<section class="combo-scenes"><div class="main-head row between"><div><h1>情绪场景</h1><p>${c.moods.length} 个情绪场景 · 一首音乐可以属于多个场景</p></div>${b(icon('plus')+'新建场景','newMood','','outline')}</div><div class="scene-layout"><aside><div class="scene-tiles">${c.moods.map(m=>`<button class="scene-tile ${scene===m.id?'selected':''}" data-action="scene" data-id="${m.id}" aria-pressed="${scene===m.id}"><strong>${esc(m.name)}${m.disabled?' · 已停用':''}</strong><small>${live().filter(t=>t.moods.includes(m.id)).length} 首可用</small></button>`).join('')}</div><div class="rule"><h3>共用同一份曲库</h3><p>曲目修改同步回音乐库。移出场景不会删除音频。</p>${b('管理标签词表','editTags','','outline')}</div></aside><section><div class="scene-summary"><div class="row between">${b('编辑说明','editMood','','outline')}${b('合并／停用','manageMood','','outline')}</div><h2>${esc(m.name)}</h2><p>${esc(m.description)}</p></div><div class="scene-heading"><h3>适用曲目</h3><div class="row">${b('从曲库添加','assign','','primary')}${b('导入','import','','outline')}</div></div>${list(scene)}<div class="rule"><h3>本地匹配</h3><p>先筛选情绪与排除标签，再比较适用标签、强度和近期播放记录。当前音乐仍适合时保持播放。</p></div></section></div></section>`;}
function connectionForm(){const p=cp();return `<div class="stack"><h2>${esc(p.name)}</h2><div class="form-grid">${field('连接名称','connName',p.name,'text','data-conn="name"')}${select('调用接口','protocol',[['chat','OpenAI Chat Completions'],['systemone','TypeSafe System One']],p.protocol,'data-conn="protocol"')}</div><p class="small">Responses、Gemini 原生、Anthropic Messages 尚未适配。品牌名称不决定接口协议。</p>${field('基础地址','base',p.base,'url','data-conn="base"')}<div class="form-grid">${select('鉴权方式','auth',[['bearer','Bearer API Key'],['header','自定义请求头'],['none','无鉴权（本地服务）']],p.auth,'data-conn="auth"')}${field('API Key · 仅保存在本机扩展','key',p.key,'password','data-conn="key" autocomplete="off"')}</div>${p.auth==='header'?`<div class="form-grid">${field('请求头名称','authHeader',p.header,'text','data-conn="header"')}${field('值前缀（可空）','prefix',p.prefix,'text','data-conn="prefix"')}</div>`:''}<details><summary>高级连接设置</summary><div class="stack">${field('请求路径','path',p.path,'text','data-conn="path"')}${field('模型列表路径（可空）','modelsPath',p.modelsPath,'text','data-conn="modelsPath"')}${field('超时（秒）','timeout',p.timeout,'number','min="5" max="120" data-conn="timeout"')}${area('非鉴权附加请求头（JSON）','headers',rawHeaders[p.id]??JSON.stringify(p.headers,null,2))}</div></details><div class="note-bar"><strong>最多一次自动尝试</strong><p>失败后等待手动重试，不轮询备用模型，不切换收费服务。</p></div><div class="row">${b(newEntity?'保存并授权服务':'保存并授权修改','saveConnection','','primary')}${b('取消','close','','outline')}${newEntity?'':b(p.disabled?'启用服务':'停用服务','toggleConnection','','outline')}${b('检查配置与权限','checkConnection','','outline')}</div><p class="small">检查配置不请求模型；真实连通性请在模型页测试一次分类。</p></div>`;}
function modelForm(){const m=mp(),p=c.connections.find(x=>x.id===m?.connectionId);if(!m||!p)return '<p>请先添加服务。</p>';return `<div class="stack"><p class="small">${newEntity?'新模型仅在保存后创建。':'修改当前模型，不自动切换功能用途。'}</p>${newEntity?select('服务来源','modelService',c.connections.filter(p=>!p.disabled).map(p=>[p.id,p.name]),m.connectionId):`<p>服务来源：${esc(p.name)}</p>`}<div class="row between"><span class="type-label">${modelKind(p)}</span>${b('获取模型列表','fetchModels','','outline')}</div><div id="modelResults"></div>${field('实际模型 ID','modelId',m.model,'text','data-model="model" placeholder="选择列表中的模型，或手动填写"')}<p class="small">请求使用此 ID。获取列表只请求服务目录，不发送剧情。</p>${field('显示名称','modelName',m.name,'text','data-model="name" placeholder="用于你自己的模型列表"')}${field('模型家族（可修改）','modelFamily',m.family??familyHint(m.model),'text','data-model="family" placeholder="无法识别时可留空"')}${b('根据模型 ID 建议名称与家族','suggestModel','','outline')}<p class="small">识别结果仅作命名建议，不验证服务商身份和模型能力。</p><details><summary>能力与高级参数</summary><div class="stack">${select('结构化输出','output',p.protocol==='systemone'?[['typed','类型化决策']]:[['json_object','JSON 对象'],['json_schema','JSON Schema（需服务支持）'],['prompt','提示词约束']],m.output,'data-model="output"')}${select('思考参数','thinking',p.protocol==='chat'&&m.model.startsWith('deepseek-')?[['omit','不发送'],['deepseek-off','DeepSeek：关闭思考（需服务支持）']]:[['omit','不发送']],m.thinking,'data-model="thinking"')}<label class="checkline"><input id="stream" type="checkbox" ${m.stream?'checked':''} ${p.protocol==='systemone'?'disabled':''} data-model="stream"> SSE 流式接收</label>${select('输出上限字段','tokenField',['max_tokens','max_completion_tokens','none'],m.tokenField,'data-model="tokenField"')}${area('附加请求体（JSON）','extra',rawExtra[m.id]??JSON.stringify(m.extra,null,2))}</div></details><div class="editor-actions">${b(newEntity?'保存模型':'保存修改','saveModel','','primary')}${b('取消','close','','outline')}${!newEntity?b(m.disabled?'启用模型':'停用模型','toggleModel','','outline'):''}</div>${!newEntity?`<div class="rule"><h3>测试已保存配置</h3><p>发送短样例，产生 1 次请求；不发送真实剧情。未保存修改不参与测试。</p>${b('测试一次分类 · 1 次请求','test','','outline')}<p id="modelTestResult" role="status">${esc(testResults[m.id]||'本次会话尚未测试')}</p></div>`:''}</div>`;}

function taskPage(){return `<section class="settings-shell"><div class="main-head"><h1>功能分配</h1><p>从已配置的模型中选择。保存不会发送请求，也不会重判当前回合。</p></div><section class="task-binding"><div><h3>当前情境判断</h3><p class="small">每回合只使用一个指定模型。</p></div><select id="sceneModel" aria-label="情境判断模型">${opts([['','请选择已配置模型'],...c.models.filter(m=>!m.disabled&&!c.connections.find(p=>p.id===m.connectionId)?.disabled&&!!m.model).map(m=>[m.id,modelName(m.id)+' · '+modelKind(c.connections.find(p=>p.id===m.connectionId))])],taskDraft.scene)}</select><span class="pill">失败不切服务</span><div class="task-secondary">${select('单曲说明转换','trackModel',[['','沿用情境判断模型'],...c.models.filter(m=>!m.disabled&&!c.connections.find(p=>p.id===m.connectionId)?.disabled&&!!m.model).map(m=>[m.id,modelName(m.id)+' · '+modelKind(c.connections.find(p=>p.id===m.connectionId))])],taskDraft.track)}<details><summary>请求用量</summary>${field('最大输出 token','maxOutput',taskDraft.maxOutput,'number','min="64" max="1024"')}${field('剧情字符上限','maxChars',taskDraft.maxChars,'number','min="2000" max="60000"')}<p>只发送必要剧情和类别，不发送整局历史或曲库。缓存命中不请求。</p></details>${b('保存用途与用量','saveTasks','','primary')}</div></section><p id="usage" class="small"></p></section>`;}
function cachePage(){return `<section class="settings-shell"><div class="main-head"><h1>剧情缓存</h1><p>按游戏与世界线管理判断记录。清理不会清空曲库或重置用量。</p></div><section class="cache-panel"><h2>回合判断缓存</h2><p id="cacheInfo" class="small" role="status">正在读取缓存数量…</p><p class="small">清除情绪判断结果与上一回合摘要，不动音乐、分类、接口配置和用量统计。当前音乐保持，当前回合不会自动重新请求。</p><select id="cacheScope" aria-label="缓存范围"><option value="all">全部游戏与世界线</option></select><div class="row">${b('清除已有回合缓存','clearCache','','outline')}${b('恢复已清除缓存','restoreCache','','outline')}</div><p class="small">清除内容保留在本地缓存回收区，可恢复；备份保留期间不释放这部分磁盘空间。</p><details><summary>可恢复的缓存保留策略</summary><div class="form-grid">${field('最多保留回合数（0 不限制）','cacheMax',c.cachePolicy?.maxRounds||0,'number','min="0" max="100000"')}${field('保留天数（0 不限制）','cacheDays',c.cachePolicy?.days||0,'number','min="0" max="3650"')}</div><p class="small">启用后在新判断完成时整理，淘汰记录仍进入回收区；不永久删除。</p>${b('保存策略','saveCachePolicy','','outline')}${b('现在按策略整理','pruneCache','','outline')}</details></section></section>`;}
function settings(){const rows=c.models.filter(m=>{const p=c.connections.find(x=>x.id===m.connectionId);return (!aiSearch||`${m.name} ${m.model} ${p?.name} ${m.family||familyHint(m.model)}`.toLowerCase().includes(aiSearch.toLowerCase()))&&(!aiFilter||(aiFilter==='disabled'?m.disabled||p?.disabled:!m.disabled&&!p?.disabled&&(aiFilter==='decision'?p?.protocol==='systemone':p?.protocol==='chat')));});return `<section class="settings-shell"><div class="main-head row between"><div><h1>模型与服务</h1><p>模型由你选择，服务独立管理。添加模型后，到功能分配中选择使用。</p></div><div class="row">${b('管理服务','page','data-id="services"','outline')}${c.connections.some(p=>!p.disabled)?b(icon('plus')+'添加模型','newModel','','primary'):b(icon('plus')+'添加服务','newConnection','','primary')}</div></div><div class="toolbar">${field('搜索模型或服务','aiSearch',aiSearch,'search','placeholder="名称、模型 ID 或家族"')}${select('模型类型','aiFilter',[['','全部模型'],['text','文本生成'],['decision','结构化决策'],['disabled','已停用']],aiFilter)}</div><p class="collection-note">${rows.length} 个模型 · 保存配置后，可在“功能分配”中指定用途。已配置不代表已连通。</p><div class="model-grid">${rows.map(m=>{const p=c.connections.find(x=>x.id===m.connectionId),family=m.family??familyHint(m.model),used=[c.tasks.scene===m.id?'剧情判断':'',(c.tasks.track||c.tasks.scene)===m.id?'说明转标签':''].filter(Boolean);return `<article class="model-card"><div class="model-identity"><div class="row"><span class="type-label">${modelKind(p)}</span><span class="model-state">${m.disabled||p?.disabled?'已停用':m.model&&p?.base&&(p.auth==='none'||p.key)?'已配置':'待配置'}</span></div><h2>${esc((m.name===p?.name?m.model:m.name)||m.model||m.name||'未命名模型')}</h2><code>${esc(m.model||'尚未填写模型 ID')}</code></div><dl><div><dt>服务来源</dt><dd>${esc(p?.name||'不存在')} · ${deployment(p?.base||'')}</dd></div><div><dt>模型家族</dt><dd>${esc(family||'未识别')}${m.family===undefined&&family?' · 规则建议':''}</dd></div><div><dt>当前用途</dt><dd>${used.join('、')||'尚未分配'}</dd></div></dl><div class="model-operations"><p class="small">${esc(testResults[m.id]||'本次会话未测试')}</p><div class="row card-actions">${b('编辑模型','editModel',`data-id="${m.id}"`,'outline')}${b('分配用途','page','data-id="tasks"','quiet')}</div></div></article>`;}).join('')||'<div class="empty"><h2>没有符合条件的模型</h2><p>添加服务并选择模型，或调整筛选。</p></div>'}</div></section>`;}
function servicesPage(){return `<section class="settings-shell"><div class="main-head row between"><div><h1>服务管理</h1><p>一个服务地址可以提供多个模型。模型品牌与服务来源分别记录。</p></div>${b(icon('plus')+'添加服务','newConnection','','primary')}</div><div class="service-list">${c.connections.map(p=>`<article class="page-card"><div class="row between"><div><h2>${esc(p.name)}</h2><p>${esc(p.base||'地址未配置')}</p></div>${b('编辑服务','editConnection',`data-id="${p.id}"`,'outline')}</div><p class="small">${deployment(p.base)} · ${p.protocol==='systemone'?'TypeSafe System One':'OpenAI Chat Completions'} · ${c.models.filter(m=>m.connectionId===p.id).length} 个模型 · ${p.disabled?'已停用':'已启用'}</p>${b('从此服务添加模型','addServiceModel',`data-id="${p.id}"`,'outline')}</article>`).join('')||'<p>尚无服务。先添加地址和鉴权，再选择模型。</p>'}</div></section>`;}

function playback(){return `<section class="page-card playback-page"><h1>播放设置</h1><div class="stack"><label class="checkline"><input id="enabled" type="checkbox" ${prefs.enabled?'checked':''} data-pref="enabled"> 开启自动配乐</label><label class="checkline"><input id="floating" type="checkbox" ${prefs.floating?'checked':''} data-pref="floating"> 显示游戏内悬浮播放器</label>${field('总音量','volume',prefs.volume,'range','min="0" max="1" step=".01" data-pref="volume"')}${field('换曲交叉淡入淡出（秒）','fade',prefs.fade,'number','min="0" max="10" step=".5" data-pref="fade"')}${select('无匹配 / 首次判断失败时','defaultTrack',[['','保持静音'],...live().map(t=>[t.id,t.name])],prefs.defaultTrack,'data-pref="defaultTrack"')}<p>离开前台游玩页停止背景播放；手动暂停保持有效。设置页主动试听独立控制。</p>${b('保存播放偏好','savePrefs','','primary')}${b('重置悬浮窗位置','resetPosition','','outline')}</div></section>`;}
function groupPage(){return ['library','categories'].includes(page)?'library':['settings','services','tasks'].includes(page)?'settings':['data','cache','trash'].includes(page)?'data':page;}
function subNavigation(){const groups:any={library:[['library','曲目库'],['categories','情绪场景']],settings:[['settings','模型与服务'],['tasks','功能分配']],data:[['data','曲库备份'],['cache','剧情缓存'],['trash','回收与恢复']]};const links=groups[groupPage()];return links?`<nav class="subnav" aria-label="${groupPage()==='settings'?'AI 配置':groupPage()==='library'?'音乐管理':'数据管理'}子导航">${links.map(([id,name])=>b(name,'page',`data-id="${id}" aria-current="${page===id?'page':'false'}"`,page===id?'active':'')).join('')}${page==='services'?'<span class="sub-location">／ 服务管理</span>':''}</nav>`:'';}
function render(){const scroll=document.querySelector('.main')?.scrollTop||0;const full=['categories','settings','services','tasks','cache','playback','diagnostics','data'].includes(page);$('app').innerHTML=`<a class="skip-link" href="#mainContent">跳到主要内容</a><header class="lab"><div class="lab-top"><div class="lab-title">随境配乐 <span>为当前故事配乐</span></div><div class="row">${b('停止试听','stop','','outline')}${b(runtime.paused?'恢复配乐':'暂停配乐','pause','id="globalPause"','outline')}</div></div></header><div class="workspace ${full?'combo-wide':''}"><aside class="sidebar"><div class="brand">${icon('music')}<span>随境<span class="brand-caption">故事的声音</span></span></div><nav class="nav" aria-label="功能导航">${[['diagnostics','配乐工作台'],['library','音乐管理'],['settings','AI 配置'],['playback','播放设置'],['data','数据管理']].map(([id,name])=>b(icon(({diagnostics:'dashboard',library:'library',settings:'model',playback:'sliders',data:'archive'})[id])+`<span>${name}</span>`,'page',`data-id="${id}" aria-current="${groupPage()===id?'page':'false'}"`,groupPage()===id?'active':'')).join('')}</nav><div class="side-bottom">${esc(modelName(c.tasks.scene))}<br>单模型判断 · 本地选曲<br>随境配乐 1.4.1</div></aside><main class="main" id="mainContent">${subNavigation()}<div id="pageError" role="alert" class="persistent-error" hidden></div>${page==='diagnostics'?diagnosticPage():page==='data'?dataPage():page==='categories'?scenes():page==='settings'?settings():page==='services'?servicesPage():page==='tasks'?taskPage():page==='cache'?cachePage():page==='playback'?playback():`<div class="main-head row between"><div><h1>${page==='trash'?'回收与恢复':'曲目库'}</h1><p>${live().length} 首音乐 · 本地保存</p></div>${page==='trash'?b('恢复曲库操作','libraryHistory','','outline'):b(icon('plus')+'导入音乐','import','','primary')}</div>${page==='library'?`<details class="import-summary"><summary>上次导入报告</summary><pre class="import-report">${esc(importReport||'本次会话尚未导入音乐')}</pre></details>`:''}<div id="liveStatus">${status()}</div><div class="toolbar"><input id="search" aria-label="搜索曲目" placeholder="搜索曲名、情绪或标签" value="${esc(search)}"><select id="filter" aria-label="情绪筛选">${opts([['','全部情绪'],['unclassified','未分类／类别停用'],['missing','音频缺失'],...c.moods.map(m=>[m.id,m.name])],filter)}</select></div>${page==='trash'?'':`<div class="row bulk-actions">${b('全选当前列表','selectVisible','','outline')}${b('取消选择','clearBulk','','outline')}${b('批量编辑','bulkEdit','','outline')}<span id="bulkCount" class="small">已选 ${bulk.size} 首</span></div>`}${list()}`}</main>${full?'':page==='trash'?'<aside class="inspector"><h2>恢复你的音乐</h2><p>曲目移入回收站后可以恢复。原始音频文件保持不变。</p></aside>':`<div class="editor-region">${editor()}</div>`}</div>`;document.documentElement.style.setProperty('--chrome-height',document.querySelector('.lab').clientHeight+'px');if(document.querySelector('.main'))document.querySelector('.main').scrollTop=scroll;void usage();void refreshCache();if(page==='diagnostics')void refreshReadiness();}
function modal(title:string,body:string){focusReturn=document.activeElement as HTMLElement;$('dialog').className=drawer?'drawer-dialog':'';$('dialog').setAttribute('aria-labelledby','dialogTitle');$('dialog').innerHTML=`<div class="dialog-head"><h2 id="dialogTitle">${title}</h2>${b(icon('close'),'close','aria-label="关闭对话框"')}</div><div id="dialogError" role="alert" class="persistent-error" hidden></div>${body}`;if(!$('dialog').open)$('dialog').showModal();}
function close(){discardAI();drawer=false;$('dialog').close();focusReturn?.focus();}
function openTrack(){drawer=true;modal('编辑曲目',editor());}
async function refreshCache(){if(!$('cacheInfo'))return;try{cacheState=await send('cacheInfo');if($('cacheScope')){const old=$('cacheScope').value;$('cacheScope').innerHTML=opts([['all','全部游戏与世界线'],...(cacheState.groups||[]).map(g=>[g.scope,`${g.title} / ${g.world||'归属未知'} · ${g.rounds} 回合 · ${(g.bytes/1024).toFixed(1)} KB`])],old);$('cacheScope').value=old||'all';}if($('cacheInfo'))$('cacheInfo').textContent=`有效回合：${cacheState.rounds} · 世界线摘要：${cacheState.worlds} · 可恢复备份：${cacheState.backups.length}`;}catch(e){if($('cacheInfo'))$('cacheInfo').textContent='缓存状态读取失败：'+e.message;}}
async function usage(){if(!$('usage'))return;const u=(await chrome.storage.local.get('usage')).usage;$('usage').textContent=u?`累计 ${u.requests} 次成功响应 · 输入 ${u.input} / 输出 ${u.output} token · ${u.unknown||0} 次用量未知（失败请求可能仍被服务计费）`:'尚无用量记录。未知 token 不计为零。';}
async function runModel(mode:string,input:any,override?:string){const snapshot=structuredClone(c);if(override)snapshot.tasks={scene:override,track:override};const {connection:p}=resolve(snapshot,mode);if(!await chrome.permissions.contains({origins:[validEndpoint(p.base)]}))throw Error('请先保存并授权连接');const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),p.timeout*1000);try{const result=await classify(snapshot,input,ctl.signal,mode);await send('recordUsage',{usage:result.usage});return result;}finally{clearTimeout(timer);}}
function capture(e:Event){const el=e.target as HTMLInputElement;const value=el.type==='checkbox'?el.checked:['number','range'].includes(el.type)?+el.value:el.value;
 if(el.dataset.bulk){el.checked?bulk.add(el.dataset.bulk):bulk.delete(el.dataset.bulk);if($('bulkCount'))$('bulkCount').textContent='已选 '+bulk.size+' 首';}
 if(el.dataset.track&&draft()){(draft() as any)[el.dataset.track]=value;if($('dirty'))$('dirty').textContent='有未保存的修改';}
 if(['moods','tags','exclude'].includes(el.dataset.check)&&draft()){const k=el.dataset.check;draft()[k]=el.checked?[...new Set([...draft()[k],el.value])]:draft()[k].filter(x=>x!==el.value);if($('dirty'))$('dirty').textContent='有未保存的修改';}
 if(el.dataset.conn)cp()[el.dataset.conn]=value;if(el.dataset.model&&mp())mp()[el.dataset.model]=value;if(el.dataset.pref)prefs[el.dataset.pref]=value;
 if(el.id==='headers'){rawHeaders[connectionId]=el.value;try{cp().headers=JSON.parse(el.value);el.setCustomValidity('');}catch{el.setCustomValidity('请输入有效 JSON');}}
 if(el.id==='extra'&&mp()){rawExtra[modelId]=el.value;try{mp().extra=JSON.parse(el.value);el.setCustomValidity('');}catch{el.setCustomValidity('请输入有效 JSON');}}
 if(el.id==='sceneModel')taskDraft.scene=el.value;if(el.id==='trackModel')taskDraft.track=el.value;if(el.id==='maxOutput')taskDraft.maxOutput=+el.value;if(el.id==='maxChars')taskDraft.maxChars=+el.value;
}
document.addEventListener('input',e=>{capture(e);const el=e.target as HTMLInputElement;if(el.id==='aiSearch'){const pos=el.selectionStart;aiSearch=el.value;render();$('aiSearch').focus();$('aiSearch').setSelectionRange(pos,pos);}if(el.id==='search'){const pos=el.selectionStart;search=el.value;render();$('search').focus();$('search').setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{capture(e);const el=e.target as HTMLInputElement;if(el.id==='filter'){filter=el.value;render();}if(el.id==='modelPick'){modelId=el.value;render();}if(el.id==='auth')refreshAI();if(el.id==='protocol'){cp().path=cp().protocol==='systemone'?'/systemone':'/chat/completions';cp().modelsPath=cp().protocol==='systemone'?'':'/models';refreshAI();}if(el.id==='modelService'){connectionId=el.value;mp().connectionId=el.value;const typed=c.connections.find(p=>p.id===el.value)?.protocol==='systemone';mp().output=typed?'typed':'prompt';mp().thinking='omit';mp().stream=false;mp().tokenField=typed?'none':'max_tokens';refreshAI();}if(el.id==='aiFilter'){aiFilter=el.value;render();}});
async function act(action:string,id:string){
 if(await advancedAction(action,id))return;
 if(action==='clearCache'){const scope=$('cacheScope')?.value||'all',label=$('cacheScope')?.selectedOptions[0]?.textContent||'全部游戏与世界线';modal('确认清理剧情缓存',`<p>范围：${esc(label)}</p><p>判断结果与对应摘要进入缓存回收区，可恢复；曲库、配置和用量保持不变，当前回合不会自动重判。</p>${b('清理并保留恢复记录','clearCacheConfirm',`data-id="${esc(scope)}"`,'primary')}${b('取消','close','','outline')}`);return;}
 if(action==='clearCacheConfirm'){const result=await send('clearCache',{scope:id||'all'});close();cacheState=result;await refreshCache();notice(`已清除 ${result.count} 条回合判断，可从缓存回收区恢复；未发送模型请求。`);return;}
 if(action==='restoreCache'){await refreshCache();if(!cacheState.backups.length)throw Error('没有可恢复的缓存备份');modal('恢复回合判断缓存',`<p>合并恢复，不覆盖清除后产生的新缓存；不会调用模型。</p>${select('选择清除记录','cacheBackup',cacheState.backups.map(x=>[x.id,new Date(x.time).toLocaleString()+' · '+x.count+' 条回合']),cacheState.backups[0].id)}${b('恢复选中记录','restoreCacheConfirm','','primary')}`);return;}
 if(action==='restoreCacheConfirm'){const result=await send('restoreCache',{id:$('cacheBackup').value});close();await refreshCache();notice(`已恢复 ${result.count} 条回合判断，已有的新缓存保持不变。`);return;}
 if(action==='page'){page=id;render();document.querySelector('.main')?.scrollTo?.(0,0);return;}
 if(action==='select'){if(page==='trash')return;selected=id;if(page==='categories')openTrack();else render();return;}
 if(action==='scene'){scene=id;render();return;}
 if(action==='close'||action==='closeDrawer'){close();return;}
 if(action==='import'){modal('导入本地音乐',`<p>音频副本保存在本机；逐个导入并汇总失败项。</p>${select('遇到内容完全相同的文件','duplicates',[['skip','跳过重复（保留原曲目）'],['copy','仍导入为独立曲目']],'skip')}${b('选择音频文件','pickAudio','','primary')}`);return;}
 if(action==='stop'){stopPreview();notice('试听已停止');return;}
 if(action==='listen'){await listen(id);return;}
 if(action==='pause'){runtime=await send('control',{command:'paused',value:!runtime.paused});render();return;}
 if(action==='saveTrack'){const t=structuredClone(draft());if(!t.name.trim()||!t.moods.length)throw Error('请填写曲名并至少选择一个适用情绪');await db.put('tracks',t);delete drafts[t.id];await send('library',{changedId:t.id});await reloadTracks();if(drawer){close();render();}else render();notice('曲目已保存');return;}
 if(action==='resetTrack'){delete drafts[selected];if(drawer){close();openTrack();}else render();return;}
 if(action==='remove'||action==='restore'){const t=tracks.find(t=>t.id===(id||selected));t.deleted=action==='remove';await db.put('tracks',t);delete drafts[t.id];stopPreview();if(drawer)close();await send('library',{changedId:t.id});await reloadTracks();render();notice(t.deleted?'已移入回收站，可随时恢复':'已恢复到曲库');return;}
 if(action==='convert'){const t=draft();if(!t?.description.trim())throw Error('请先填写适用说明');const target=t.id;notice('正在转换说明 · 一次请求');const r=await runModel('track',{description:t.description.slice(0,6000)});modal('标签建议',`<p>情绪：${esc(moodName(r.decision.mood))}</p><p>适用：${esc(r.decision.tags.join('、')||'无')}</p><p>排除：${esc(r.decision.exclude?.join('、')||'无')}</p><p>应用后还需保存曲目。</p>${b('应用到曲目草稿','applyTags',`data-id="${target}"`,'primary')}`);($('dialog') as any).suggestion=r.decision;return;}
 if(action==='applyTags'){const d=drafts[id]??structuredClone(tracks.find(t=>t.id===id)),r=$('dialog').suggestion;if(!d||!r)return;d.moods=[r.mood];d.tags=r.tags;d.exclude=r.exclude||[];d.intensity=r.intensity;drafts[id]=d;selected=id;close();render();if(page==='categories')openTrack();notice('已应用到草稿，请检查后保存');return;}
 if(action==='newMood'||action==='editMood'){const m=action==='editMood'?c.moods.find(m=>m.id===scene):null;modal(m?'编辑场景':'新建场景',`<div class="stack">${field('类别名称','moodName',m?.name||'')}${area('什么情况下使用？','moodDesc',m?.description||'')}${b('保存场景','saveMood',`data-id="${m?.id||''}"`,'primary')}</div>`);return;}
 if(action==='saveMood'){const name=$('moodName').value.trim(),description=$('moodDesc').value.trim();if(!name||!description)throw Error('请填写名称和说明');if(c.moods.some(m=>m.name===name&&m.id!==id))throw Error('已有同名类别');if(c.moods.filter(m=>!m.disabled).length>=24&&!id)throw Error('为控制输入体积，情绪类别最多 24 个');const m={...(c.moods.find(x=>x.id===id)||{}),id:id||crypto.randomUUID(),name:name.slice(0,40),description:description.slice(0,300)};await persist({moods:id?c.moods.map(x=>x.id===id?m:x):[...c.moods,m]});scene=m.id;close();render();notice('场景已保存；后续回合使用新定义，不自动重新请求当前回合');return;}
 if(action==='editTags'){modal('管理标签词表',`<p>最多 40 个。已有曲目使用的标签不能直接移除，请先编辑相关曲目。</p>${area('逗号分隔标签','tags',c.tags.join('，'))}${b('保存标签','saveTags','','primary')}`);return;}
 if(action==='saveTags'){const tags=[...new Set<string>($('tags').value.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean))];if(!tags.length||tags.length>40||tags.some(t=>t.length>30))throw Error('请设置 1–40 个标签，每个不超过 30 字');const used=tracks.flatMap(t=>[...t.tags,...t.exclude]);if(c.tags.some(t=>!tags.includes(t)&&used.includes(t)))throw Error('被移除的标签仍有曲目使用（包含回收站），请先编辑曲目');await persist({tags});close();render();return;}
 if(action==='assign'){modal('关联到「'+esc(moodName(scene))+'」',`<p>只修改场景关联，不复制或删除音频。</p><div class="assign-list">${live().map(t=>`<label class="checkline"><input type="checkbox" data-assign="${t.id}" ${t.moods.includes(scene)?'checked':''}>${esc(t.name)}</label>`).join('')}</div>${b('保存场景关联','saveAssign','','primary')}`);return;}
 if(action==='saveAssign'){const updates:Track[]=[];for(const input of document.querySelectorAll<HTMLInputElement>('[data-assign]')){const t=structuredClone(tracks.find(t=>t.id===input.dataset.assign));const was=t.moods.includes(scene);if(was===input.checked)continue;if(drafts[t.id]&&JSON.stringify(drafts[t.id])!==JSON.stringify(t))throw Error('该曲目有未保存草稿，请先保存或还原后再关联');t.moods=t.moods.filter(m=>m!==scene);if(input.checked)t.moods.push(scene);if(!t.moods.length)throw Error('曲目至少保留一个情绪，请先在曲目编辑中设置其他情绪');updates.push(t);}await db.putTracks(updates);await send('library');await reloadTracks();close();render();notice('场景与曲库已同步');return;}
 if(action==='connection'){connectionId=id;modelId=c.models.find(m=>m.connectionId===id)?.id||'';render();return;}
 if(action==='section'){section=id;render();return;}
 if(action==='newConnection'){connectionId=crypto.randomUUID();connectionDrafts[connectionId]={id:connectionId,name:'',base:'',key:'',protocol:'chat',auth:'bearer',header:'x-api-key',prefix:'',path:'/chat/completions',modelsPath:'/models',timeout:30,headers:{}};newEntity=true;aiEditor='connection';refreshAI();return;}
 if(action==='editConnection'){connectionId=id;newEntity=false;aiEditor='connection';refreshAI();return;}
 if(action==='saveConnection'||action==='checkConnection'){if($('headers')&&!$('headers').reportValidity())return;const p=structuredClone(cp());if(rawHeaders[p.id]!==undefined)p.headers=JSON.parse(rawHeaders[p.id]);validateConnection(p);const origin=validEndpoint(p.base);if(action==='checkConnection'){const permitted=await chrome.permissions.contains({origins:[origin]});notice(permitted?'配置与来源权限通过；未请求模型，不代表真实连接成功':'配置通过，但尚未授权此接口来源');return;}const changed=c.connections.find(x=>x.id===p.id)?.protocol!==p.protocol;if(changed&&c.models.some(m=>m.connectionId===p.id))throw Error('已有模型的服务不能直接切换协议，请新增服务，避免破坏模型能力配置');if(!await chrome.permissions.request({origins:[origin]}))throw Error('未获得接口访问权限；草稿保留，尚未保存');await persist({connections:newEntity?[...c.connections,p]:c.connections.map(x=>x.id===p.id?p:x)});close();page='services';render();notice('服务已保存；现在可以添加模型，未发送分类请求');return;}
 if(action==='newModel'||action==='addServiceModel'){const p=(id?c.connections.find(p=>p.id===id):c.connections.find(p=>p.id===connectionId&&!p.disabled))||c.connections.find(p=>!p.disabled);if(!p){page='services';render();throw Error('请先添加并启用一个服务');}connectionId=p.id;modelId=crypto.randomUUID();modelDrafts[modelId]={id:modelId,connectionId,name:'',model:'',output:p.protocol==='systemone'?'typed':'prompt',thinking:'omit',tokenField:p.protocol==='systemone'?'none':'max_tokens',stream:false,extra:{}};newEntity=true;aiEditor='model';refreshAI();return;}
 if(action==='editModel'){modelId=id;connectionId=c.models.find(m=>m.id===id).connectionId;newEntity=false;aiEditor='model';refreshAI();return;}
 if(action==='suggestModel'){const m=mp();if(!m.model.trim())throw Error('请先填写或选择模型 ID');m.family=familyHint(m.model);m.name=m.family?`${m.family} · ${m.model}`:m.model;refreshAI();return;}
 if(action==='saveModel'){if($('extra')&&!$('extra').reportValidity())return;const m=structuredClone(mp()),p=c.connections.find(p=>p.id===m.connectionId);if(rawExtra[m.id]!==undefined)m.extra=JSON.parse(rawExtra[m.id]);validateModel(m,p);await persist({models:newEntity?[...c.models,m]:c.models.map(x=>x.id===m.id?m:x)});delete testResults[m.id];close();page='settings';render();notice('模型已保存；到功能分配中选择使用，不自动切换');return;}
 if(action==='saveTasks'){const d=taskDraft;if(!d.scene)throw Error('请选择剧情判断使用的模型');if(!Number.isFinite(d.maxOutput)||d.maxOutput<64||d.maxOutput>1024||!Number.isFinite(d.maxChars)||d.maxChars<2000||d.maxChars>60000)throw Error('输出上限 64–1024，剧情字符上限 2000–60000');for(const id of [d.scene,d.track].filter(Boolean)){const m=c.models.find(m=>m.id===id);if(!m)throw Error('请选择模型');validateModel(m,c.connections.find(p=>p.id===m.connectionId));}await persist({tasks:{scene:d.scene,track:d.track},maxOutput:Math.round(d.maxOutput),maxChars:Math.round(d.maxChars)});render();notice('用途与用量已保存；当前回合不自动重判');return;}
 if(action==='savePrefs'){if(!Number.isFinite(prefs.fade)||prefs.fade<0||prefs.fade>10)throw Error('过渡应为 0–10 秒');await persist(prefs);render();notice('播放偏好已保存');return;}
 if(action==='test'){delete testResults[modelId];if($('modelTestResult'))$('modelTestResult').textContent='正在测试已保存配置…';notice('正在发送短示例 · 一次请求');const r=await runModel('scene',{story:'雨后小镇恢复宁静，旅人在旅馆喝茶休息。'},modelId);testResults[modelId]=`本次测试成功 · ${r.usage.ms}ms · 输入 ${r.usage.input??'未知'} token`;if($('modelTestResult'))$('modelTestResult').textContent=testResults[modelId];notice('已测试保存的配置：'+moodName(r.decision.mood));return;}
 if(action==='fetchModels'){const p=c.connections.find(p=>p.id===connectionId);if(!await chrome.permissions.contains({origins:[validEndpoint(p.base)]}))throw Error('请先保存并授权服务');const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),p.timeout*1000);try{const ids=await modelList(c,connectionId,ctl.signal);$('modelResults').innerHTML=`${select('服务返回的模型列表','fetchedModel',ids,ids[0])}${b('使用所选模型','useFetched','','outline')}`;}finally{clearTimeout(timer);}return;}
 if(action==='useFetched'){const m=mp();m.model=$('fetchedModel').value;m.family=familyHint(m.model);m.name=m.family?`${m.family} · ${m.model}`:m.model;refreshAI();return;}

}
document.addEventListener('click',e=>{const button=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-action]');if(!button)return;void (async()=>{if(busy){notice('上一次操作尚未完成，请稍候');return;}busy=true;button.disabled=true;const errorBox=$('dialog').open?$('dialogError'):$('pageError');if(errorBox)errorBox.hidden=true;try{await act(button.dataset.action,button.dataset.id||'');}catch(e){if(button.dataset.action==='test'){testResults[modelId]='本次测试失败；请检查下方错误提示';if($('modelTestResult'))$('modelTestResult').textContent=testResults[modelId];}const box=$('dialog').open?$('dialogError'):$('pageError');if(box){box.hidden=false;box.textContent=e.name==='AbortError'?'请求超时或已取消，未自动重试':e.message||String(e);}notice(e.name==='AbortError'?'请求超时或已取消；未自动重试':e.message||String(e),8000);}finally{busy=false;button.disabled=false;}})();});
$('files').onchange=async()=>{if(busy){notice('请等待当前操作完成后重新导入');return;}busy=true;const files=Array.from<File>($('files').files),errors:string[]=[];let n=0,duplicates=0;try{for(let i=0;i<files.length;i++){const file=files[i];notice(`正在导入 ${i+1}/${files.length}：${file.name}`,30000);try{if(!file.size)throw Error('文件为空');if(file.size>512*1048576)throw Error('单个文件超过 512MB');const fingerprint=await fileFingerprint(file);for(const old of tracks.filter(t=>!t.fingerprint&&t.size===file.size)){const record=await db.get('blobs',old.id);if(record?.blob){old.fingerprint=await fileFingerprint(record.blob);await db.put('tracks',old);if(drafts[old.id])drafts[old.id].fingerprint=old.fingerprint;}}if(duplicatePolicy==='skip'&&tracks.some(t=>t.fingerprint===fingerprint)){duplicates++;continue;}const t:Track={id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),moods:page==='categories'?[scene]:[],tags:[],exclude:[],description:'',gain:.8,intensity:-1,size:file.size,type:file.type,fingerprint};await db.importTrack(t,file);tracks.push(t);selected=t.id;n++;}catch(e){errors.push(file.name+'：'+e.message);}}await send('library');}finally{importReport=`共 ${files.length} 个文件；成功 ${n}，跳过重复 ${duplicates}，失败 ${errors.length}。\n`+errors.join('\n');$('files').value='';busy=false;await reloadTracks();render();modal('音频导入结果',`<pre class="import-report">${esc(importReport)}</pre><p>新曲目请选择适用情绪后保存；完整记录可在曲目库的“上次导入报告”查看。</p>${b('知道了','close','','primary')}`);notice(`已导入 ${n} 首，失败 ${errors.length} 项`);}};
$('backupFile').onchange=async()=>{const file=$('backupFile').files[0];$('backupFile').value='';if(!file)return;if(busy){notice('请等待当前操作完成');return;}busy=true;try{if(file.size>750*1048576)throw Error('备份文件超过 750MB，请使用较小的备份');backupInput=validateBundle(JSON.parse(await file.text()));const duplicate=backupInput.tracks.filter(t=>tracks.some(x=>x.id===t.id||t.fingerprint&&x.fingerprint===t.fingerprint)).length;modal('备份预检',`<p>格式版本 ${backupInput.version} · ${backupInput.tracks.length} 首资料 · ${backupInput.audio.length} 份音频 · ${duplicate} 首重复。</p>${select('重复记录处理','backupMode',[['skip','跳过已有记录'],['copy','导入为独立副本']],'skip')}${b('预览合并结果','confirmBackup','','primary')}`);}catch(e){notice('备份无法导入：'+e.message,8000);}finally{busy=false;}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPreview();});window.addEventListener('pagehide',stopPreview);$('dialog').addEventListener('close',()=>{discardAI();drawer=false;});
window.addEventListener('beforeunload',e=>{const dirty=Object.values(drafts).some(t=>JSON.stringify(t)!==JSON.stringify(tracks.find(x=>x.id===t.id)))||Object.keys(connectionDrafts).some(id=>JSON.stringify(connectionDrafts[id])!==JSON.stringify(c.connections.find(x=>x.id===id)))||Object.keys(modelDrafts).some(id=>JSON.stringify(modelDrafts[id])!==JSON.stringify(c.models.find(x=>x.id===id)));if(dirty||Object.keys(rawHeaders).length||Object.keys(rawExtra).length||JSON.stringify(taskDraft)!==JSON.stringify({...c.tasks,maxOutput:c.maxOutput||220,maxChars:c.maxChars})||Object.entries(prefs).some(([k,v])=>c[k]!==v)){e.preventDefault();e.returnValue='';}});
async function init(){await send('state');c=upgradeConfig((await chrome.storage.local.get('config')).config);try{connectionId=resolve(c).connection.id;modelId=resolve(c).model.id;}catch{connectionId=c.connections[0]?.id;modelId=c.models.find(m=>m.connectionId===connectionId)?.id||'';}scene=c.moods[0].id;taskDraft={...c.tasks,maxOutput:c.maxOutput||220,maxChars:c.maxChars};prefs={enabled:c.enabled,floating:c.floating,volume:c.volume,fade:c.fade,defaultTrack:c.defaultTrack};await reloadTracks();runtime=await send('state');render();setInterval(async()=>{try{runtime=await send('state');if($('globalPause'))$('globalPause').textContent=runtime.paused?'恢复配乐':'暂停配乐';if($('liveStatus'))$('liveStatus').innerHTML=status();if(page==='diagnostics')void refreshReadiness();}catch{}},1500);}
void init().catch(e=>{$('app').textContent='设置页加载失败：'+e.message;});
function diagnosticPage(){return `<section class="settings-shell"><div class="main-head"><h1>配乐工作台</h1><p>连接模型 → 导入音乐 → 分类保存 → 开始配乐。</p></div><div class="dashboard-grid"><div class="page-card now-playing"><h2>当前配乐</h2><div id="runtimeDetail"></div><label class="label" for="targetGame">选择已连接的游玩页</label><select id="targetGame"></select><p class="small">开始配乐将恢复自动播放，并对当前完整剧情判断；缓存命中不新增请求。锁曲／锁情绪保持有效。请返回游戏页执行。</p><div class="row">${b('开始配乐','startMusic','','primary')}${b('下一首','nextMusic','','outline')}${b('固定此游戏','pinGame','','outline')}${b('取消固定','unpinGame','','outline')}${b('刷新检查','refreshReady','','outline')}</div></div><div class="page-card selection-panel"><h2>本次选曲依据</h2><div id="selectionDetail"></div></div></div><details class="readiness-panel"><summary id="readinessSummary">运行检查 · 查看准备情况</summary><div id="readyChecks" class="stack"><p>正在读取就绪状态…</p></div></details><div class="row">${b('复制脱敏诊断','copyDiagnostics','','outline')}${b('配置模型','page','data-id="settings"','outline')}${b('导入并分类音乐','page','data-id="library"','outline')}${b('播放偏好','page','data-id="playback"','outline')}</div><p class="small">诊断不请求 AI，默认不包含密钥、鉴权头、剧情全文或文件名。未连接时请刷新游戏页，并在扩展管理页检查网站访问权限。</p></section>`;}
let readinessBusy=false;
async function refreshReadiness(){if(readinessBusy||!$('readyChecks'))return;readinessBusy=true;try{readyState=await send('readiness');if(!$('readyChecks'))return;if($('readinessSummary'))$('readinessSummary').textContent=readyState.allReady?'运行检查 · 准备就绪':`运行检查 · ${readyState.checks.filter(x=>!x.ok).length} 项待处理`;$('readyChecks').innerHTML=`<p class="small">版本 ${esc(readyState.version)} · ${readyState.allReady?'基础条件已就绪':'还有准备项未完成'}</p>`+readyState.checks.map(x=>`<div class="check-result"><strong>${x.ok?'✓':'○'} ${esc(x.name)}</strong><span>${esc(x.detail)}</span></div>`).join('');runtime=await send('state');if(!$('runtimeDetail'))return;$('runtimeDetail').innerHTML=`<p><strong>${esc(runtime.status)}</strong></p><p>当前曲目：${esc(runtime.trackName||'尚未播放')}</p><p>${esc(runtime.error||'')}</p><small>状态时间：${runtime.statusTime?new Date(runtime.statusTime).toLocaleTimeString():'未知'}</small><p>控制来源：${esc(runtime.source?`${runtime.source.title} / ${runtime.source.world} / 第 ${runtime.source.turn} 回合`:'尚未连接')}</p><p>固定标签页：${runtime.pinnedTab?'已固定':'跟随前台游玩页'}</p>`;const old=$('targetGame').value;$('targetGame').innerHTML=opts(readyState.targets.map(t=>[String(t.tabId),`${t.title} · ${t.connected?'已连接':'未连接'} · ${t.turn??'?'} 回合`]),old||String(runtime.pinnedTab||readyState.targets[0]?.tabId||''));const e=runtime.explanation,expanded=!!$('selectionDetail').querySelector('details[open]');$('selectionDetail').innerHTML=`<p>判断来源：${esc(({cache:'缓存',model:'模型',manual:'手动锁定'})[runtime.resultSource]||'尚无判断')}</p><p>情绪：${esc(runtime.lockMood?moodName(runtime.lockMood):runtime.decision?moodName(runtime.decision.mood):'—')} · 强度：${runtime.decision?.intensity??'—'} · 标签：${esc(runtime.decision?.tags?.join('、')||'—')}</p>${e?`<p>${esc(e.summary)} · ${e.candidates} 首候选</p><details ${expanded?'open':''}><summary>查看本地匹配结果</summary>${(e.reasons||[]).map(r=>`<p>${esc(r.name)}：${esc(r.reason)}${r.score===null?'':' · '+r.score+' 分'}</p>`).join('')}</details>`:'<p>尚未选曲；这里仅展示已有分类和本地规则，不额外请求 AI。</p>'}`;}catch(e){if($('readyChecks'))$('readyChecks').textContent='无法连接后台：'+e.message;}finally{readinessBusy=false;}}
function dataPage(){return `<section class="settings-shell backup-layout"><div class="main-head"><h1>曲库备份</h1><p>曲库资料与音频可迁移，密钥和模型连接不包含在备份中。</p></div><div class="page-card"><h2>导出曲库</h2><label class="checkline"><input type="checkbox" id="includeAudio"> 包含音频副本（最多 512MB 原始音频；文件较大时请稍候）</label><p>仅资料备份适合保留分类；迁移到新浏览器时，未包含音频的曲目会标记为音频缺失。</p>${b('导出备份文件','exportLibrary','','primary')}</div><div class="page-card"><h2>导入备份</h2><p>先预检格式、数量、缺失音频及重复记录，再选择合并。不会直接覆盖现有曲目。</p>${b('选择备份文件','pickBackup','','outline')}</div><div class="page-card"><h2>可恢复的曲库操作</h2><p>批量修改、备份导入、场景合并与停用保留恢复记录。恢复前请保存当前草稿。</p>${b('查看恢复记录','libraryHistory','','outline')}</div></section>`;}
function ensureCleanTracks(){if(Object.values(drafts).some(t=>JSON.stringify(t)!==JSON.stringify(tracks.find(x=>x.id===t.id))))throw Error('有未保存的曲目草稿，请先保存或还原再执行批量／恢复操作');}
let duplicatePolicy='skip';
async function advancedAction(action:string,id:string):Promise<boolean>{
 if(action==='nextMusic'){runtime=await send('control',{command:'next'});await refreshReadiness();return true;}
 if(action==='startMusic'){runtime=await send('control',{command:'start',value:$('targetGame')?.value});notice('已准备开始，请返回所选游戏页；当前锁定保持有效。');await refreshReadiness();return true;}
 if(action==='refreshReady'){await refreshReadiness();return true;}
 if(action==='pinGame'||action==='unpinGame'){const target=action==='pinGame'?$('targetGame').value:null;if(action==='pinGame'&&!target)throw Error('没有可固定的游戏');runtime=await send('control',{command:'pinTab',value:target});await refreshReadiness();return true;}
 if(action==='copyDiagnostics'){const d=await send('diagnostics'),text=JSON.stringify(d,null,2);try{await navigator.clipboard.writeText(text);notice('已复制脱敏诊断，无密钥和剧情全文');}catch{modal('脱敏诊断',area('可选择并复制以下内容','diagnosticText',text,'readonly'));}return true;}
 if(action==='resetPosition'){runtime=await send('control',{command:'floatPosition',value:null});notice('悬浮窗位置已重置');return true;}
 if(action==='toggleConnection'||action==='toggleModel'){const p=c.connections.find(x=>x.id===connectionId),m=c.models.find(x=>x.id===modelId);if(action==='toggleConnection'){await persist({connections:c.connections.map(x=>x.id===p.id?{...x,disabled:!x.disabled}:x)});delete connectionDrafts[p.id];}else{await persist({models:c.models.map(x=>x.id===m.id?{...x,disabled:!x.disabled}:x)});delete modelDrafts[m.id];}close();render();notice('启用状态已保存；未切换任务模型');return true;}
 if(action==='saveCachePolicy'){await persist({cachePolicy:{maxRounds:+$('cacheMax').value,days:+$('cacheDays').value}});notice('缓存保留策略已保存，之后淘汰记录仍可恢复');return true;}
 if(action==='pruneCache'){const r=await send('clearCache',{policy:true});await refreshCache();notice(`已将 ${r.count} 条过期／超量记录移至缓存回收区`);return true;}
 if(action==='selectVisible'){for(const input of document.querySelectorAll<HTMLInputElement>('[data-bulk]'))bulk.add(input.dataset.bulk);render();return true;}
 if(action==='clearBulk'){bulk.clear();render();return true;}
 if(action==='bulkEdit'){ensureCleanTracks();if(!bulk.size)throw Error('请先勾选曲目');modal('批量编辑 '+bulk.size+' 首音乐',`<p>只修改情绪与适用标签，排除标签、说明、音量和强度保持不变。</p>${select('修改方式','batchMode',[['append','追加到已有情绪／标签'],['replace','替换已有情绪／标签']],'append')}${checks('适用情绪','batchMoods',c.moods.filter(m=>!m.disabled).map(m=>[m.id,m.name]),[])}${checks('适用标签','batchTags',c.tags,[])}${b('保存批量修改','saveBulk','','primary')}`);return true;}
 if(action==='saveBulk'){ensureCleanTracks();const moods=[...document.querySelectorAll<HTMLInputElement>('[data-check=batchMoods]:checked')].map(x=>x.value),tags=[...document.querySelectorAll<HTMLInputElement>('[data-check=batchTags]:checked')].map(x=>x.value),mode=$('batchMode').value;if(mode==='replace'&&!moods.length)throw Error('替换时至少选择一个情绪');const changes=batchTracks(tracks,[...bulk],moods,tags,mode);await db.changeLibrary(changes,[],{label:'批量编辑曲目'});drafts={};await reloadTracks();await send('library');close();render();notice(`已更新 ${changes.length} 首，可在数据管理 → 回收与恢复中撤销`);return true;}
 if(action==='manageMood'){ensureCleanTracks();const m=c.moods.find(x=>x.id===scene),affected=tracks.filter(t=>t.moods.includes(scene));modal('管理「'+esc(m.name)+'」',`<p>影响 ${affected.length} 首曲目（含回收站）。停用保留关联，合并将关联改到目标类别并停用原类别；操作可恢复。</p><details><summary>受影响曲目</summary>${affected.map(t=>`<p>${esc(t.name)}</p>`).join('')||'没有关联曲目'}</details>${b(m.disabled?'重新启用类别':'停用类别','toggleMood','','outline')}${select('合并到另一个启用类别','mergeTarget',c.moods.filter(x=>x.id!==scene&&!x.disabled).map(x=>[x.id,x.name]),'')}${b('合并并保留恢复记录','mergeMood','','primary')}`);return true;}
 if(action==='mergeMood'||action==='toggleMood'){ensureCleanTracks();c=upgradeConfig(await send(action,{from:scene,to:$('mergeTarget')?.value}));drafts={};await reloadTracks();close();render();notice('类别与曲目关联已更新，锁定状态已同步，可恢复');return true;}
 if(action==='exportLibrary'){notice('正在生成本地备份，不调用 AI…',30000);const data=await exportLibrary(c,$('includeAudio').checked);download('随境配乐-曲库-'+new Date().toISOString().slice(0,10)+'.omni.json',data);notice('已生成备份，请在浏览器下载记录中确认文件');return true;}
 if(action==='pickBackup'){$('backupFile').click();return true;}
 if(action==='confirmBackup'){ensureCleanTracks();const mode=$('backupMode').value;const plan=planImport(backupInput,c,tracks,mode);modal('确认合并备份',`<p>将新增 ${plan.tracks.length} 首，跳过 ${plan.skipped} 首重复记录；${plan.missing} 首未包含音频。</p><p>原曲目不覆盖；操作保留恢复记录。</p>${b('执行合并','applyBackup',`data-id="${mode}"`,'primary')}`);return true;}
 if(action==='applyBackup'){ensureCleanTracks();const result=await importLibrary(backupInput,c,id==='copy'?'copy':'skip');try{await persist({moods:result.moods,tags:result.tags});}catch(e){await db.restoreLibrary(result.archive);throw e;}drafts={};await reloadTracks();await send('library');close();render();notice(`已导入 ${result.tracks.length} 首，缺失音频 ${result.missing} 首`);backupInput=null;return true;}
 if(action==='libraryHistory'){const archives=await db.libraryArchives();if(!archives.length)throw Error('尚无可恢复的曲库操作');modal('曲库恢复记录',`<p>恢复会还原该批次影响的曲目，覆盖这些曲目后续编辑；当前状态另存为撤销记录。新导入曲目会移入回收站，音频不会删除。</p>${select('选择恢复批次','libraryArchive',archives.map(x=>[x.id,new Date(x.time).toLocaleString()+' · '+x.label+' · '+x.count+' 首']),archives[0].id)}${b('恢复选定批次','restoreLibrary','','primary')}`);return true;}
 if(action==='restoreLibrary'){ensureCleanTracks();c=upgradeConfig(await send('restoreLibrary',{id:$('libraryArchive').value}));drafts={};await reloadTracks();await send('library');close();render();notice('已恢复曲库操作，恢复前状态也已保留');return true;}
 if(action==='pickAudio'){duplicatePolicy=$('duplicates').value;close();$('files').click();return true;}
 return false;
}

function discardAI(){if(aiEditor==='connection'){delete connectionDrafts[connectionId];delete rawHeaders[connectionId];}if(aiEditor==='model'){delete modelDrafts[modelId];delete rawExtra[modelId];}aiEditor='';newEntity=false;}
function refreshAI(){const priorFocus=document.activeElement as HTMLElement;drawer=true;modal(aiEditor==='connection'?(newEntity?'添加服务':'编辑服务'):(newEntity?'添加模型':'编辑模型'),aiEditor==='connection'?connectionForm():modelForm());$('dialog').classList.add('ai-drawer');const next=priorFocus?.id?$(priorFocus.id):null;(next||$('dialog').querySelector('input,select,textarea,button'))?.focus();if(priorFocus?.closest('dialog'))focusReturn=document.querySelector(aiEditor==='connection'?'[data-action=newConnection]':'[data-action=newModel]') as HTMLElement;}
